  order_status text,
  order_purchase_timestamp timestamp,
  order_approved_at timestamp,
  order_delivered_carrier_date timestamp,
  order_delivered_customer_date timestamp,
  order_estimated_delivery_date timestamp,
  PRIMARY KEY (order_id)
);

INSERT INTO sales.orders (order_id, customer_id, order_status, order_purchase_timestamp, order_approved_at, order_delivered_carrier_date, order_delivered_customer_date, order_estimated_delivery_date)
SELECT
  order_id,
  customer_id,
  order_status,
  NULLIF(trim(order_purchase_timestamp), '')::timestamp,
  NULLIF(trim(order_approved_at), '')::timestamp,
  NULLIF(trim(order_delivered_carrier_date), '')::timestamp,
  NULLIF(trim(order_delivered_customer_date), '')::timestamp,
  NULLIF(trim(order_estimated_delivery_date), '')::timestamp
FROM raw.orders;

CREATE TABLE sales.order_items (
