);

INSERT INTO sales.order_items (order_id, order_item_id, product_id, seller_id, shipping_limit_date, price, freight_value)
SELECT
  order_id,
  NULLIF(trim(order_item_id), '')::numeric::integer,
  product_id,
  seller_id,
  NULLIF(trim(shipping_limit_date), '')::timestamp,
  NULLIF(trim(price), '')::numeric(12,2),
  NULLIF(trim(freight_value), '')::numeric(12,2)
FROM raw.order_items;

CREATE TABLE sales.order_payments (
  order_id text,
