  payment_installments integer,
  payment_value numeric(12,2),
  PRIMARY KEY (order_id, payment_sequential)
);

INSERT INTO sales.order_payments (order_id, payment_sequential, payment_type, payment_installments, payment_value)
SELECT
  order_id,
  NULLIF(trim(payment_sequential), '')::numeric::integer,
  payment_type,
